INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'vi', '{"name":"Song Tử","dateRange":"21/5 – 20/6","rulingPlanet":"Sao Thủy","summary":"Song Tử tò mò, thích trò chuyện và luôn muốn nhìn một câu chuyện từ nhiều phía.","originStory":"Song Tử đại diện cho Castor và Pollux, cặp song sinh gắn bó chọn chia sẻ sự bất tử thay vì xa nhau. Chòm sao của họ mang chủ đề đồng hành, góc nhìn hai chiều, giao tiếp và sự chuyển động giữa các thế giới.","traits":["Tò mò","Linh hoạt","Giàu biểu đạt","Nhanh trí"],"strengths":["Giao tiếp","Đa năng","Học hỏi nhanh"],"challenges":["Bồn chồn","Phân tán chú ý","Suy nghĩ quá nhiều"],"compatibleSigns":["Thiên Bình","Bảo Bình","Bạch Dương"],"reflectionPrompt":"Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Song Tử mang năng lượng Khí. Song Tử tò mò, thích trò chuyện và luôn muốn nhìn một câu chuyện từ nhiều phía.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh giao tiếp, đa năng, học hỏi nhanh giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng tò mò, linh hoạt, giàu biểu đạt, nhanh trí làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi bồn chồn, phân tán chú ý, suy nghĩ quá nhiều bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Song Tử mang năng lượng Khí. Song Tử tò mò, thích trò chuyện và luôn muốn nhìn một câu chuyện từ nhiều phía.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh giao tiếp, đa năng, học hỏi nhanh giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng tò mò, linh hoạt, giàu biểu đạt, nhanh trí làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi bồn chồn, phân tán chú ý, suy nghĩ quá nhiều bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Song Tử mang năng lượng Khí. Song Tử tò mò, thích trò chuyện và luôn muốn nhìn một câu chuyện từ nhiều phía.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh giao tiếp, đa năng, học hỏi nhanh giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng tò mò, linh hoạt, giàu biểu đạt, nhanh trí làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi bồn chồn, phân tán chú ý, suy nghĩ quá nhiều bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn.","guidance":"Trở lại định hướng này trong suốt năm: Cứ khám phá điều khiến bạn tò mò, rồi dành thời gian hiểu sâu hơn."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'vi', '{"name":"Cự Giải","dateRange":"21/6 – 22/7","rulingPlanet":"Mặt Trăng","summary":"Cự Giải nhạy cảm, biết quan tâm và luôn trân trọng gia đình, ký ức cùng cảm giác được thuộc về.","originStory":"Cự Giải gắn với cua Karkinos, được đưa lên bầu trời sau khi thể hiện lòng trung thành trong trận chiến giữa Heracles và Hydra. Mai cua cùng sự chủ quản của Mặt Trăng tượng trưng cho che chở, những đợt thủy triều cảm xúc và sự tận tâm với người thân cận.","traits":["Trực giác tốt","Chu đáo","Biết che chở","Giàu tưởng tượng"],"strengths":["Đồng cảm","Trung thành","Thấu hiểu cảm xúc"],"challenges":["Tâm trạng thất thường","Thu mình sau lớp phòng vệ","Dễ chạnh lòng"],"compatibleSigns":["Bọ Cạp","Song Ngư","Kim Ngưu"],"reflectionPrompt":"Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Cự Giải mang năng lượng Nước. Cự Giải nhạy cảm, biết quan tâm và luôn trân trọng gia đình, ký ức cùng cảm giác được thuộc về.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đồng cảm, trung thành, thấu hiểu cảm xúc giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng trực giác tốt, chu đáo, biết che chở, giàu tưởng tượng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi tâm trạng thất thường, thu mình sau lớp phòng vệ, dễ chạnh lòng bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Cự Giải mang năng lượng Nước. Cự Giải nhạy cảm, biết quan tâm và luôn trân trọng gia đình, ký ức cùng cảm giác được thuộc về.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh đồng cảm, trung thành, thấu hiểu cảm xúc giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng trực giác tốt, chu đáo, biết che chở, giàu tưởng tượng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi tâm trạng thất thường, thu mình sau lớp phòng vệ, dễ chạnh lòng bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Cự Giải mang năng lượng Nước. Cự Giải nhạy cảm, biết quan tâm và luôn trân trọng gia đình, ký ức cùng cảm giác được thuộc về.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh đồng cảm, trung thành, thấu hiểu cảm xúc giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng trực giác tốt, chu đáo, biết che chở, giàu tưởng tượng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi tâm trạng thất thường, thu mình sau lớp phòng vệ, dễ chạnh lòng bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn.","guidance":"Trở lại định hướng này trong suốt năm: Chăm sóc cảm xúc của mình và cho người khác cơ hội đến gần bạn."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'vi', '{"name":"Sư Tử","dateRange":"23/7 – 22/8","rulingPlanet":"Mặt Trời","summary":"Sư Tử ấm áp, sáng tạo và thích thể hiện bản thân. Sự hào phóng của cung này thường truyền cảm hứng cho người khác.","originStory":"Sư Tử gắn với sư tử Nemea, sinh vật gần như bất khả xâm phạm bị đánh bại trong chiến công đầu tiên của Heracles. Được đưa lên bầu trời, nó trở thành biểu tượng của can đảm, phong thái uy nghi và sức sáng tạo của Mặt Trời.","traits":["Ấm áp","Sáng tạo","Rộng lượng","Tự tin"],"strengths":["Lãnh đạo","Trung thành","Biểu đạt chân thành"],"challenges":["Kiêu hãnh","Cần được ghi nhận","Phóng đại trở ngại"],"compatibleSigns":["Bạch Dương","Nhân Mã","Thiên Bình"],"reflectionPrompt":"Hãy tự tin tỏa sáng và cũng dành chỗ để người khác được ghi nhận."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Sư Tử mang năng lượng Lửa. Sư Tử ấm áp, sáng tạo và thích thể hiện bản thân. Sự hào phóng của cung này thường truyền cảm hứng cho người khác.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh lãnh đạo, trung thành, biểu đạt chân thành giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng ấm áp, sáng tạo, rộng lượng, tự tin làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi kiêu hãnh, cần được ghi nhận, phóng đại trở ngại bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Hãy tự tin tỏa sáng và cũng dành chỗ để người khác được ghi nhận.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Hãy tự tin tỏa sáng và cũng dành chỗ để người khác được ghi nhận."}');
