INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'es-419', '{"name":"Virgo","dateRange":"23 de agosto – 22 de septiembre","rulingPlanet":"Mercurio","summary":"El discernimiento y el servicio guían a la Doncella, convirtiendo la observación cuidadosa en mejora práctica.","originStory":"Virgo a menudo se asocia con Astrea, la doncella de la justicia que permaneció con la humanidad después de que otros dioses se retiraran. El trigo que lleva vincula al signo con la cosecha, la habilidad, la pureza de intención y el cuidado de lo que sostiene la vida.","traits":["Observante","Práctico","Reflexivo","Preciso"],"strengths":["Análisis","Artesanía","Servicio útil"],"challenges":["perfeccionismo","Autocrítica","Preocuparse por los detalles"],"compatibleSigns":["Tauro","Capricornio","Cáncer"],"reflectionPrompt":"Mejore lo que pueda y permita que el buen trabajo esté completo antes de que sea perfecto."}');
