INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'es-419', '{"name":"Libra","dateRange":"23 de septiembre – 22 de octubre","rulingPlanet":"Venus","summary":"El equilibrio, la belleza y la reciprocidad guían la Balanza hacia elecciones que honran cada voz.","originStory":"La balanza de Libra la lleva Astraea, diosa de la justicia, y forma el único símbolo inanimado del zodíaco. Representan el juicio mesurado, la armonía social y el trabajo continuo para restaurar el equilibrio en lugar de suponer que ya existe.","traits":["Diplomático","imparcial","Encantador","Colaborativo"],"strengths":["Mediación","Perspectiva","Creando armonía"],"challenges":["Indecisión","complacer a la gente","Evitar el conflicto necesario"],"compatibleSigns":["Géminis","Acuario","León"],"reflectionPrompt":"Busca la justicia sin abandonar la verdad de tus propias necesidades."}');
