INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'es-419', '{"name":"Escorpio","dateRange":"23 de octubre – 21 de noviembre","rulingPlanet":"Plutón","summary":"La profundidad y la transformación definen al Escorpión, cuya perspicacia encuentra la verdad debajo de la superficie.","originStory":"Escorpio recuerda al escorpión enviado a enfrentar al cazador Orión después de que su orgullo perturbó el orden natural. Sus lugares opuestos en el cielo evocan límites, consecuencia, misterio y el poder regenerativo que se encuentra después de un final.","traits":["Intenso","Perceptivo","Leal","Ingenioso"],"strengths":["coraje emocional","Enfocar","Transformación"],"challenges":["Secretismo","Sospecha","guardar rencores"],"compatibleSigns":["Cáncer","Piscis","Virgo"],"reflectionPrompt":"Usa tu profundidad para transformar la verdad, no para esconderla."}');
